SELECT 'app-only-transactions', 'App-Only Transactions', 'code', 'Easy', 'Fintech',
       'NULL Handling', ARRAY['is-null']::text[], 'Digital adoption tracking: return `txn_id`, `user_id`, and `txn_type` of transactions done **without an agent** (no agent involved), newest first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT txn_id, user_id, txn_type FROM transactions WHERE agent_id IS NULL ORDER BY txn_at DESC;',
       '["App-only means agent_id IS NULL","Never write = NULL"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 77
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'app-only-transactions');

