SELECT 'dhaka-agents', 'Agent Points in Dhaka', 'code', 'Easy', 'Fintech',
       'Filtering', ARRAY['where']::text[], 'Field ops is visiting Dhaka agent points today. Return `agent_id` and `shop_name` of agents in the Dhaka district, alphabetical by shop name.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT agent_id, shop_name FROM agents WHERE district = ''Dhaka'' ORDER BY shop_name;',
       '["Filter agents by district","ORDER BY shop_name"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 88
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'dhaka-agents');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'fee-revenue-by-type', 'Fee Revenue by Transaction Type', 'code', 'Easy', 'Fintech',
       'Aggregation', ARRAY['sum','group-by']::text[], 'Fees are the business. For successful transactions, return each `txn_type` and total `fee_revenue`, highest first. Skip types that earned nothing.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT txn_type, SUM(fee) AS fee_revenue
FROM transactions WHERE status = ''success''
GROUP BY txn_type HAVING SUM(fee) > 0 ORDER BY fee_revenue DESC;',
       '["SUM(fee) per type","HAVING SUM(fee) > 0 drops zero-fee types"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 68
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'fee-revenue-by-type');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'unverified-active-users', 'Unverified but Transacting', 'code', 'Medium', 'Fintech',
       'Joins', ARRAY['join','distinct']::text[], 'Compliance red flag: users who are **not KYC-verified** yet have successful transactions. Return each such user''s `user_id` and `name` once, ordered by user_id.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT DISTINCT u.user_id, u.name
FROM users u JOIN transactions t ON t.user_id = u.user_id
WHERE u.kyc_verified = false AND t.status = ''success''
ORDER BY u.user_id;',
       '["Join and filter kyc_verified = false","DISTINCT prevents one row per transaction"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 63
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'unverified-active-users');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'avg-txn-size-by-district', 'Average Ticket Size by District', 'code', 'Medium', 'Fintech',
       'Aggregation', ARRAY['avg','join','round']::text[], 'Marketing segments districts by ticket size. Return user `district` and the average successful transaction `amount` (`avg_amount`, 2 decimals), highest first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT u.district, ROUND(AVG(t.amount), 2) AS avg_amount
FROM users u JOIN transactions t ON t.user_id = u.user_id
WHERE t.status = ''success''
GROUP BY u.district ORDER BY avg_amount DESC;',
       '["District lives on users","ROUND(AVG(amount), 2)"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 60
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'avg-txn-size-by-district');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'first-transaction-per-user', 'Each User''s First Transaction', 'code', 'Medium', 'Fintech',
       'Window Functions', ARRAY['row-number','first-event']::text[], 'Onboarding analysis: what do users do first? Return `user_id`, `txn_type`, and `txn_at` of each user''s **earliest** transaction, ordered by user_id.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT user_id, txn_type, txn_at FROM (
  SELECT user_id, txn_type, txn_at,
         ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY txn_at) AS rn
  FROM transactions
) t WHERE rn = 1 ORDER BY user_id;',
       '["ROW_NUMBER() ordered by txn_at ascending","Keep rn = 1"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 52
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'first-transaction-per-user');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'share-of-volume-by-type', 'Each Type''s Share of Volume', 'code', 'Hard', 'Fintech',
       'Window Functions', ARRAY['window','ratio']::text[], 'The exec deck wants percentages, not raw sums. For successful transactions, return `txn_type`, `type_volume`, and `pct_share` of total volume (1 decimal), highest share first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT txn_type, SUM(amount) AS type_volume,
