SELECT 'collections-priority-list', 'Case: Monday Collections Priority List', 'case_study', 'Medium', 'Fintech',
       'Joins', ARRAY['left-join','coalesce']::text[], '**Scenario.** The collections team starts Monday with a priority list: every non-paid loan and how much is still outstanding.

For loans not in `paid` status, return `loan_id`, `borrower`, `district`, and `outstanding` (principal minus total repaid; loans with zero repayments count fully outstanding), largest first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_microloan'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_microloan'), ''), 'SELECT l.loan_id, l.borrower, l.district,
       l.principal - COALESCE(SUM(r.amount), 0) AS outstanding
FROM loans l LEFT JOIN repayments r ON r.loan_id = l.loan_id
WHERE l.status <> ''paid''
GROUP BY l.loan_id, l.borrower, l.district, l.principal
ORDER BY outstanding DESC;',
       '["LEFT JOIN keeps loans with no repayments","COALESCE(SUM(amount), 0) turns no-repayment NULL into 0","Outstanding = principal - repaid"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 49
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'collections-priority-list');

