SELECT 'revenue-rank-in-category', 'Revenue Rank Within Category', 'code', 'Hard', 'E-Commerce',
       'Window Functions', ARRAY['rank','partition']::text[], 'For **delivered** sales, rank products **within their category** by revenue. Return `category`, `name`, `revenue`, and `rank_in_category`, ordered by category then rank.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), 'SELECT category, name, revenue,
       RANK() OVER (PARTITION BY category ORDER BY revenue DESC) AS rank_in_category
FROM (
  SELECT p.category, p.name, SUM(oi.quantity * oi.unit_price) AS revenue
  FROM products p
  JOIN order_items oi ON oi.product_id = p.product_id
  JOIN orders o ON o.order_id = oi.order_id
  WHERE o.status = ''delivered''
  GROUP BY p.category, p.name
) t ORDER BY category, rank_in_category;',
