SELECT 'aov-by-city', 'Average Order Value by City', 'code', 'Hard', 'E-Commerce',
       'Subqueries', ARRAY['cte','avg']::text[], 'City economics: average **delivered** order value per customer city (`aov`, 2 decimals), highest first. (Average of order totals — not the total divided by item count.)',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), 'WITH order_values AS (
  SELECT o.order_id, c.city, SUM(oi.quantity * oi.unit_price) AS order_value
