SELECT 'free-shipping-threshold', 'Case: Setting the Free-Shipping Threshold', 'case_study', 'Medium', 'E-Commerce',
       'Aggregation', ARRAY['percentile','order-value']::text[], '**Scenario.** Growth wants free shipping above a threshold that most orders *almost* reach. As the first input, they need every delivered order''s value and how it compares to the average.

Return `order_id`, `order_value`, and `vs_avg` (order value minus the average delivered order value, 2 decimals), highest value first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), 'WITH vals AS (
