  FROM orders o JOIN order_items oi ON oi.order_id = o.order_id
  WHERE o.status = ''delivered''
  GROUP BY o.order_id
)
SELECT order_id, order_value, ROUND(order_value - AVG(order_value) OVER (), 2) AS vs_avg
FROM vals ORDER BY order_value DESC;',
       '["Per-order values in a CTE","AVG(...) OVER () compares each row to the overall average without collapsing rows"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 43
