SELECT 'category-return-rate', 'Case: Category Return Rates', 'case_study', 'Hard', 'E-Commerce',
       'Conditional Aggregation', ARRAY['ratio','case-when']::text[], '**Scenario.** Supplier scorecards need a defect proxy: of each category''s ordered units (delivered + returned orders only), what share sat in returned orders?

Return `category`, `units_total`, `units_returned`, and `return_rate_pct` (1 decimal), highest rate first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), 'SELECT p.category,
       SUM(oi.quantity) AS units_total,
       SUM(CASE WHEN o.status = ''returned'' THEN oi.quantity ELSE 0 END) AS units_returned,
       ROUND(100.0 * SUM(CASE WHEN o.status = ''returned'' THEN oi.quantity ELSE 0 END) / SUM(oi.quantity), 1) AS return_rate_pct
FROM products p
JOIN order_items oi ON oi.product_id = p.product_id
JOIN orders o ON o.order_id = oi.order_id
WHERE o.status IN (''delivered'',''returned'')
GROUP BY p.category
ORDER BY return_rate_pct DESC;',
       '["Restrict to the two statuses in WHERE","Returned units via conditional SUM","Rate = returned / total units"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, 1800, 32
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'category-return-rate');

