SELECT 'rider-cod-vs-prepaid', 'Rider Workload: COD vs Prepaid', 'code', 'Hard', 'Logistics',
       'Conditional Aggregation', ARRAY['case-when']::text[], 'Cash handling is risk. Per rider (delivered runs only), return `name`, `cod_deliveries`, and `prepaid_deliveries` in one row each, most COD first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'logistics_courier'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'logistics_courier'), ''), 'SELECT r.name,
       SUM(CASE WHEN p.cod_amount > 0 THEN 1 ELSE 0 END) AS cod_deliveries,
