SELECT 'fastest-delivery-per-hub', 'Fastest Delivery per Hub', 'code', 'Hard', 'Logistics',
       'Window Functions', ARRAY['row-number','extract']::text[], 'Bragging rights: each hub''s single fastest delivered run. Return hub `city`, rider `name`, and `minutes` (pickup to delivery, whole minutes), fastest overall first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'logistics_courier'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'logistics_courier'), ''), 'SELECT city, name, minutes FROM (
  SELECT h.city, r.name,
         ROUND(EXTRACT(EPOCH FROM (d.delivered_at - d.picked_at)) / 60) AS minutes,
         ROW_NUMBER() OVER (PARTITION BY h.hub_id ORDER BY d.delivered_at - d.picked_at) AS rn
  FROM hubs h
  JOIN riders r ON r.hub_id = h.hub_id
  JOIN deliveries d ON d.rider_id = r.rider_id
  WHERE d.status = ''delivered''
) t WHERE rn = 1 ORDER BY minutes;',
       '["Duration = delivered_at - picked_at","ROW_NUMBER per hub ordered by duration ascending","EPOCH/60 for minutes"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, 1800, 33
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'fastest-delivery-per-hub');

