INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'failed-first-attempt-cost', 'Case: The Cost of Failed First Attempts', 'case_study', 'Hard', 'Logistics',
       'Window Functions', ARRAY['lag','attempts']::text[], '**Scenario.** Every failed first attempt means a re-dispatch. Ops wants the parcels whose **first attempt failed**, and whether a later attempt rescued them.

Return `parcel_id`, first attempt''s `status` (`first_status`), and `rescued` (true if any later attempt delivered).',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'logistics_courier'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'logistics_courier'), ''), 'WITH ranked AS (
  SELECT parcel_id, status,
         ROW_NUMBER() OVER (PARTITION BY parcel_id ORDER BY picked_at) AS attempt_no
  FROM deliveries
)
SELECT f.parcel_id, f.status AS first_status,
       EXISTS (
         SELECT 1 FROM ranked l
         WHERE l.parcel_id = f.parcel_id AND l.attempt_no > 1 AND l.status = ''delivered''
       ) AS rescued
FROM ranked f
