SELECT 'data-vs-plan-allowance', 'Usage vs Plan Allowance', 'code', 'Hard', 'Telco',
       'Joins', ARRAY['ratio','multi-join']::text[], 'Who''s outgrowing their plan? Per subscriber, compare recorded total data (GB) to the plan''s monthly allowance. Return `name`, plan `allowance_gb`, `used_gb` (2 decimals), and `pct_of_allowance` (1 decimal), highest percentage first.',
