SELECT 'arpu-by-plan', 'Case: ARPU by Plan', 'case_study', 'Medium', 'Telco',
       'Joins', ARRAY['arpu','avg']::text[], '**Scenario.** The pricing committee reviews ARPU (average recharge revenue per user) plan by plan before the next tariff filing.

Per plan, return `name`, subscriber count (`subs`), total recharge revenue (`revenue`), and `arpu` (revenue ÷ subs, 2 decimals), highest ARPU first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'telco_network'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'telco_network'), ''), 'SELECT p.name, COUNT(DISTINCT s.sub_id) AS subs,
       COALESCE(SUM(r.amount), 0) AS revenue,
       ROUND(COALESCE(SUM(r.amount), 0) / COUNT(DISTINCT s.sub_id), 2) AS arpu
FROM plans p
JOIN subscribers s ON s.plan_id = p.plan_id
LEFT JOIN recharges r ON r.sub_id = s.sub_id
GROUP BY p.name ORDER BY arpu DESC;',
       '["COUNT(DISTINCT sub_id) — recharges duplicate subscriber rows","LEFT JOIN keeps plans whose subs never recharged","ARPU = revenue / subs"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 42
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'arpu-by-plan');

