SELECT 'inactive-data-users', 'Case: Paying but Barely Using', 'case_study', 'Medium', 'Telco',
       'Subqueries', ARRAY['avg','comparison']::text[], '**Scenario.** Retention suspects some subscribers pay for data they never use — prime downgrade-offer targets.

Return `name` and `avg_daily_mb` (average daily data, 1 decimal) of subscribers whose average is **below the overall average** across all subscriber-days, lowest first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'telco_network'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'telco_network'), ''), 'SELECT s.name, ROUND(AVG(u.data_mb), 1) AS avg_daily_mb
FROM subscribers s JOIN usage_daily u ON u.sub_id = s.sub_id
GROUP BY s.name
HAVING AVG(u.data_mb) < (SELECT AVG(data_mb) FROM usage_daily)
ORDER BY avg_daily_mb;',
       '["Overall average via a scalar subquery","Compare per-subscriber AVG in HAVING"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 45
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'inactive-data-users');

