SELECT 'collections-1-book-overview', 'Step 1: Size the Book', 'code', 'Easy', 'Fintech',
       'Aggregation', ARRAY['group-by']::text[], 'First, the shape of the book by geography: return `district`, number of loans (`loans`), and total `principal` disbursed (`disbursed`), largest book first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_microloan'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_microloan'), ''), 'SELECT district, COUNT(*) AS loans, SUM(principal) AS disbursed
FROM loans GROUP BY district ORDER BY disbursed DESC;',
       '["GROUP BY district","COUNT and SUM together"]'::jsonb, '[]'::jsonb, NULL,
       (SELECT id FROM public.careerprep_questions WHERE slug = 'mission-collections-sprint'), 0, NULL, 78
