INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'collections-2-recovery-rate', 'Step 2: Recovery Rate per District', 'code', 'Medium', 'Fintech',
       'Joins', ARRAY['left-join','ratio']::text[], 'Now the health metric: per district, how much of the disbursed principal has come back? Return `district`, `disbursed`, `recovered`, and `recovery_pct` (1 decimal), lowest recovery first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_microloan'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_microloan'), ''), 'SELECT l.district, SUM(DISTINCT_PRINCIPAL.principal) AS disbursed,
       COALESCE(SUM(r.amount), 0) AS recovered,
       ROUND(100.0 * COALESCE(SUM(r.amount), 0) / SUM(DISTINCT_PRINCIPAL.principal), 1) AS recovery_pct
FROM loans l
JOIN LATERAL (SELECT l.principal) DISTINCT_PRINCIPAL ON true
LEFT JOIN repayments r ON r.loan_id = l.loan_id
GROUP BY l.district
ORDER BY recovery_pct;',
       '["Careful: joining repayments duplicates loan rows — aggregate repayments per loan first, or sum principal separately","A subquery per loan (or CTE) avoids double-counting principal","Recovery = repaid / disbursed"]'::jsonb, '[]'::jsonb, NULL,
       (SELECT id FROM public.careerprep_questions WHERE slug = 'mission-collections-sprint'), 1, NULL, 38
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'collections-2-recovery-rate');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'collections-3-slow-payers', 'Step 3: The Slow Payers', 'code', 'Medium', 'Fintech',
       'Aggregation', ARRAY['having','date']::text[], 'District view done — now names. Active loans whose **last repayment** was before 1 May 2026 are officially slow. Return `loan_id`, `borrower`, and `last_paid`, oldest last payment first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_microloan'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_microloan'), ''), 'SELECT l.loan_id, l.borrower, MAX(r.paid_on) AS last_paid
FROM loans l JOIN repayments r ON r.loan_id = l.loan_id
WHERE l.status = ''active''
GROUP BY l.loan_id, l.borrower
HAVING MAX(r.paid_on) < ''2026-05-01''
ORDER BY last_paid;',
       '["MAX(paid_on) per loan is the last payment","The cutoff test on an aggregate goes in HAVING"]'::jsonb, '[]'::jsonb, NULL,
       (SELECT id FROM public.careerprep_questions WHERE slug = 'mission-collections-sprint'), 2, NULL, 51
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'collections-3-slow-payers');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'collections-4-call-list', 'Step 4: The Call List', 'code', 'Hard', 'Fintech',
       'Subqueries', ARRAY['cte','outstanding']::text[], 'Final deliverable: the ranked call list. For every **non-paid** loan, compute outstanding (principal − repaid) and rank by outstanding descending. Return `rank`, `borrower`, `district`, `status`, and `outstanding`.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_microloan'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_microloan'), ''), 'WITH repaid AS (
  SELECT loan_id, SUM(amount) AS total FROM repayments GROUP BY loan_id
)
SELECT RANK() OVER (ORDER BY l.principal - COALESCE(rp.total, 0) DESC) AS rank,
       l.borrower, l.district, l.status,
       l.principal - COALESCE(rp.total, 0) AS outstanding
FROM loans l LEFT JOIN repaid rp ON rp.loan_id = l.loan_id
WHERE l.status <> ''paid''
ORDER BY outstanding DESC;',
       '["A CTE of repayments per loan keeps the main query clean","RANK() OVER (ORDER BY outstanding DESC)","COALESCE for never-paid loans"]'::jsonb, '[]'::jsonb, NULL,
       (SELECT id FROM public.careerprep_questions WHERE slug = 'mission-collections-sprint'), 3, 1800, 29
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'collections-4-call-list');

