INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'sla-2-duration-distribution', 'Step 2: How Long Deliveries Take', 'code', 'Medium', 'Logistics',
       'Date Functions', ARRAY['extract','bucketing']::text[], 'The SLA is 6 hours. Bucket **delivered** runs into `''within_sla''` (≤ 6h) and `''breached''` (> 6h). Return `bucket` and `runs`, breaches first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'logistics_courier'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'logistics_courier'), ''), 'SELECT CASE WHEN EXTRACT(EPOCH FROM (delivered_at - picked_at)) / 3600 <= 6
            THEN ''within_sla'' ELSE ''breached'' END AS bucket,
       COUNT(*) AS runs
FROM deliveries WHERE status = ''delivered''
GROUP BY 1 ORDER BY bucket;',
       '["Hours = EPOCH difference / 3600","CASE builds the bucket label","GROUP BY 1 groups by the first select expression"]'::jsonb, '[]'::jsonb, NULL,
       (SELECT id FROM public.careerprep_questions WHERE slug = 'mission-sla-crunch'), 1, NULL, 49
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'sla-2-duration-distribution');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
