SELECT 'sla-3-rider-breach-rate', 'Step 3: Breaches by Rider', 'code', 'Medium', 'Logistics',
       'Conditional Aggregation', ARRAY['case-when','ratio']::text[], 'Now names: per rider (delivered runs), return `name`, `total_runs`, `breaches` (> 6h), most breaches first, ties by name.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'logistics_courier'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'logistics_courier'), ''), 'SELECT r.name, COUNT(*) AS total_runs,
       SUM(CASE WHEN EXTRACT(EPOCH FROM (d.delivered_at - d.picked_at)) / 3600 > 6 THEN 1 ELSE 0 END) AS breaches
FROM riders r JOIN deliveries d ON d.rider_id = r.rider_id
WHERE d.status = ''delivered''
GROUP BY r.name ORDER BY breaches DESC, name;',
       '["Reuse the 6-hour test inside a conditional SUM","Count total and breaches in the same pass"]'::jsonb, '[]'::jsonb, NULL,
       (SELECT id FROM public.careerprep_questions WHERE slug = 'mission-sla-crunch'), 2, NULL, 47
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'sla-3-rider-breach-rate');

