SELECT 'sla-4-worst-runs-report', 'Step 4: The Evidence Pack', 'code', 'Hard', 'Logistics',
       'Window Functions', ARRAY['rank','report']::text[], 'For the client call, rank the 5 slowest delivered runs. Return `rank`, parcel `parcel_id`, rider `name`, `hours` (1 decimal), slowest first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'logistics_courier'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'logistics_courier'), ''), 'SELECT RANK() OVER (ORDER BY d.delivered_at - d.picked_at DESC) AS rank,
       d.parcel_id, r.name,
