SELECT 'congestion-1-daily-network-load', 'Step 1: Daily Network Load', 'code', 'Easy', 'Telco',
       'Aggregation', ARRAY['group-by','sum']::text[], 'Start with the macro picture: total data consumed per `usage_date` (`total_mb`), in date order.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'telco_network'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'telco_network'), ''), 'SELECT usage_date, SUM(data_mb) AS total_mb FROM usage_daily GROUP BY usage_date ORDER BY usage_date;',
